import{_ as t,c as a,o,a3 as d}from"./chunks/framework.BNw1pucY.js";const m=JSON.parse('{"title":"Access","description":"Who can view, deploy, and manage a deployed bot.","frontmatter":{"title":"Access","description":"Who can view, deploy, and manage a deployed bot."},"headers":[],"relativePath":"reference/access.md","filePath":"reference/access.md"}'),r={name:"reference/access.md"};function c(n,e,s,h,i,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h1><p><a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a> calls the three access levels Viewer, Editor, and Owner, and the API calls them <code>viewer</code>, <code>deployer</code>, and <code>admin</code>. <code>admin</code> is Owner, and a write also accepts <code>owner</code> for that role and <code>editor</code> for Editor.</p><table tabindex="0"><thead><tr><th>Dashboard</th><th>API value</th><th>What it allows</th></tr></thead><tbody><tr><td>Viewer</td><td><code>viewer</code></td><td>Open the bot</td></tr><tr><td>Editor</td><td><code>deployer</code></td><td>Deploy, stop, and restart</td></tr><tr><td>Owner</td><td><code>admin</code></td><td>Editor, plus secrets and who else has access</td></tr></tbody></table><p>A new deploy gives the person who deployed it Owner and the team that owns the bot Viewer. Deploying that bot again does not change who has access. A team that already has access keeps it.</p><p>A deploy from a service account, such as CI, gives Owner to the person who created that account. The service account is not an Owner. If the account has no creating person, the team is Viewer and a team Admin can manage the bot.</p><p>A team Admin can manage every bot that team owns, including a bot the team can only view. The same person cannot manage a bot another team published, including a catalog bot installed into their team.</p><p>An Owner changes who has access in <a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a>.</p>',7)])])}const w=t(r,[["render",c]]);export{m as __pageData,w as default};
